# dl.php's file name: the last path segment of ?f=, never one starting with
# a dot, at most 120 characters (a release's longest is under 50). Anything
# else is answered 404.
map $arg_f $iptv_dl_file {
    default "";
    "~^(?:.*/)?(?<iptv_f>[A-Za-z0-9_~-][A-Za-z0-9._~-]{0,119})$" $iptv_f;
}

# -- statistics -----------------------------------------------------------------
# One line per page view (only / and /help/), per /hit and per download,
# handed to the donate service over its socket (access_log syslog:...
# below; donate/stats_inbox.py) - never written to a file. The lines wait in
# the service's memory until its own thread counts them, a minute at most:
# counts per day and, for the admin page's visitor log, each visit without
# its address (see donate/stats_collect.py's docstring for what is kept and
# how long). So no log anywhere holds a visitor's address. The page that
# linked here is not sent at all: the page's own /hit says it, as the
# statistics read it (its site, its path without the query). Each value is
# cut so a line fits one datagram (2 KiB, FreeBSD's default).
# Of the rest of the sender's own words, as much as the statistics read: the
# browser's name to 512 characters (stats_collect.py's UA_MAX), the address
# asked for to 1024, the method to 16 - each could be 8k, a line 24k and
# more of whatever was sent.
map $request_method $iptv_log_method {
    default "";
    "~^(?<iptv_log_m1>.{1,16})" $iptv_log_m1;
}
map $http_user_agent $iptv_log_ua {
    default "";
    "~^(?<iptv_log_ua1>.{1,512})" $iptv_log_ua1;
}
# Of the address asked for, only what the statistics read. A page (/,
# /help/): its path - never its query, which can carry whatever a link
# put there (?fbclid=, ?utm_..., a ?lang= the page's language "l" says
# already). /hit: the fields the page's signal sends (nav.js) and
# stats_collect.py reads, each as sent and in this order - one left out is
# empty, which the statistics read as not sent - and nothing else of its
# query; the page that linked last, the longest, so the cut below takes it
# before the rest. Lines from before have the whole address; the
# statistics read both alike.
map $request_uri $iptv_log_uri_kept {
    default "";
    "~^/hit(?:\?|$)" "/hit?p=$arg_p&ev=$arg_ev&t=$arg_t&x=$arg_x&n=$arg_n&s=$arg_s&l=$arg_l&bl=$arg_bl&w=$arg_w&h=$arg_h&hl=$arg_hl&r=$arg_r";
    "~^(?<iptv_log_path>[^?]+)" $iptv_log_path;
}
map $iptv_log_uri_kept $iptv_log_uri {
    default "";
    "~^(?<iptv_log_uri1>.{1,1024})" $iptv_log_uri1;
}
log_format iptv_stats escape=json
    '{"ip":"$http_x_real_ip","t":"$time_iso8601","m":"$iptv_log_method",'
    '"u":"$iptv_log_uri","s":$status,"a":"$iptv_log_ua","l":"$iptv_lang"}';
# A browser that has opened the admin page (donate.py sets iptv_nostats) is
# the site's owner testing: neither its page views nor its downloads are
# logged, so neither the statistics nor the public download counter count it.
map $cookie_iptv_nostats $iptv_count {
    default 1;
    "1"     0;
}
# A download, for the statistics (to the service's socket, as above):
# nginx's "combined" with the visitor's address as a last field
# ($remote_addr is the TLS proxy), so stats_collect.py can count a visitor
# once per file per day - and no page that linked ("-"). Of the request
# line only the method, the file's name ($iptv_dl_file: the last part of
# ?f=, 120 characters at the most, "" for one that is no file's) and the
# protocol - nothing else the link carried. The browser's name cut short as
# above; no user name ("-" where combined has $remote_user).
log_format iptv_dl '$remote_addr - - [$time_local] "$iptv_log_method /dl.php?f=$iptv_dl_file $server_protocol" '
    '$status $body_bytes_sent "-" "$iptv_log_ua" "$http_x_real_ip"';
# The public download counter's own log (sync-releases.sh counts it into
# downloads.json): the request line as above, the answer, and what asked -
# the app, a robot that says so, nothing, or a browser ($iptv_ua_kind) -
# and nothing else: no address, no time, no browser's name.
map $http_user_agent $iptv_ua_kind {
    default "browser";
    ""      "none";
    "-"     "none";
    "~*^dopeiptv/" "app";
    "~*(bot|crawl|spider|slurp|preview|facebookexternalhit|whatsapp|telegram|discord|skype|embed|monitor|scan)" "robot";
}
log_format iptv_dl_count '"$iptv_log_method /dl.php?f=$iptv_dl_file $server_protocol" $status $iptv_ua_kind';

# -- the pages ------------------------------------------------------------
# No-cache: a returning visitor always checks for a new page (a new
# release, new counts) - the PHP pages were never cached either.
location = / {
    access_log syslog:server=unix:/var/run/iptv_donate/stats.sock,nohostname,tag=iptv_stats iptv_stats if=$iptv_count;
    add_header Vary $iptv_vary;
    add_header Set-Cookie $iptv_set_cookie;
    add_header Cache-Control "no-cache";
    try_files /i18n/$iptv_lang/index.html =404;
}
location = /help/ {
    access_log syslog:server=unix:/var/run/iptv_donate/stats.sock,nohostname,tag=iptv_stats iptv_stats if=$iptv_count;
    add_header Vary $iptv_vary;
    add_header Set-Cookie $iptv_set_cookie;
    add_header Cache-Control "no-cache";
    try_files /i18n/$iptv_lang/help/index.html =404;
}

# Every download link goes through /dl.php?f=NAME, which sends the browser
# on to /files/NAME. Only a file that is there; anything else is plain
# "Not found". These requests go to the statistics (the service's socket)
# and to a log of their own without an address, where sync-releases.sh
# counts the downloads (newsyslog keeps .0 uncompressed for it, see
# DEPLOY.md).
#
# Counted against iptv_dl first, then answered in @iptv_dl: nginx runs a
# location's return before its limit_req (the rewrite phase comes before
# the one limits are checked in), so a limit beside a return is never
# applied - try_files hands on only after it. /.iptv-none is never there.
location = /dl.php {
    limit_req zone=iptv_dl burst=60 nodelay;
    limit_req_status 429;
    try_files /.iptv-none @iptv_dl;
}
location @iptv_dl {
    access_log syslog:server=unix:/var/run/iptv_donate/stats.sock,nohostname,tag=iptv_dl iptv_dl if=$iptv_count;
    access_log /var/log/nginx/iptv.dope.rs-dl-counts.log iptv_dl_count if=$iptv_count;
    default_type text/plain;
    if ($iptv_dl_file = "") {
        return 404 "Not found";
    }
    if ($iptv_dl_nightly != "") {
        return 302 https://github.com/slimture/dopeIPTV/releases/download/$iptv_dl_nightly/$iptv_dl_file;
    }
    if (!-f $document_root/files/$iptv_dl_file) {
        return 404 "Not found";
    }
    return 302 /files/$iptv_dl_file;
}

# -- statistics -------------------------------------------------------------
# A page tells /hit when it is shown in a browser, how long it was looked
# at, the tip dialog's opening (nav.js) and a support link's click
# (events.js); only the log line counts.
# Counted first, then answered in @iptv_hit, as /dl.php is: beside the
# return the limit was never applied.
location = /hit {
    limit_req zone=iptv_hit burst=60 nodelay;
    limit_req_status 429;
    client_max_body_size 1k;
    try_files /.iptv-none @iptv_hit;
}
location @iptv_hit {
    access_log syslog:server=unix:/var/run/iptv_donate/stats.sock,nohostname,tag=iptv_stats iptv_stats if=$iptv_count;
    add_header Cache-Control "no-store" always;
    add_header X-Robots-Tag "noindex, nofollow" always;
    return 204;
}

# Where the address may not leave the site: the admin pages, the support
# page (Stripe sends people back to it with their checkout's id) and the
# Trakt sign-in's way back to the app.
map $uri $dopeiptv_referrer {
    default              "strict-origin-when-cross-origin";
    ~^/admin(?:/|$)      "no-referrer";
    ~^/support(?:/|$)    "no-referrer";
    ~^/trakt/            "no-referrer";
}
# The admin pages in a window of their own: a page they open, or one that
# opened them, cannot reach into them (Cross-Origin-Opener-Policy). Not the
# rest of the site: a payment's window (Google Pay's, a bank's check) may
# talk back to the page that opened it.
map $uri $dopeiptv_coop {
    default              "";
    ~^/admin(?:/|$)      "same-origin";
}
# What only the site's own pages and the app read - the admin pages and the
# services' answers - never loaded into another site's page as an image or
# a script (Cross-Origin-Resource-Policy). The app is not a browser and
# never sees it; the pages, files and downloads stay for everyone.
map $uri $dopeiptv_corp {
    default                                   "";
    ~^/admin(?:/|$)                           "same-origin";
    ~^/(?:sync|together|feedback|donate)/     "same-origin";
    ~^/(?:support/key|hit)$                   "same-origin";
}

# https only, for a year, the names under it too, as the proxy's http
# block says for every site; never in a frame of another site; a file's type is
# what it is sent as, never guessed (a download is never run as a
# script); the address kept to the site where it says so (the map).
add_header Content-Security-Policy   $csp_policy always;
add_header Content-Security-Policy   "frame-ancestors 'none'" always;
add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;
add_header X-Content-Type-Options    "nosniff" always;
add_header X-Frame-Options           "DENY" always;
add_header Referrer-Policy           $dopeiptv_referrer always;
proxy_hide_header Referrer-Policy;
# No page of the site, nor a frame in it, may use what the site never
# does - left alone: payment (Apple Pay, Google Pay), passkeys
# (publickey-credentials-*), copying (clipboard-write), sharing a link
# (web-share), and whatever else is not named.
add_header Permissions-Policy        "camera=(), microphone=(), geolocation=(), display-capture=(), usb=(), serial=(), hid=(), bluetooth=(), midi=(), idle-detection=(), xr-spatial-tracking=(), browsing-topics=()" always;
add_header Cross-Origin-Opener-Policy   $dopeiptv_coop always;
add_header Cross-Origin-Resource-Policy $dopeiptv_corp always;

# nginx's version in no answer, its error pages included.
server_tokens off;

# https only, for a year, as dopeiptv.org's: an old link typed or saved
# as http:// is not asked in the clear again.
add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;

# Chosen by ?lang=: remembered - sent over https only (the site has no
# other), and not along when another site's page posts here or loads a
# part of it. Chosen otherwise: varies by visitor.
map $iptv_lang_arg $iptv_set_cookie {
    "" "";
    default "lang=$iptv_lang_arg; Max-Age=31536000; path=/; Secure; SameSite=Lax";
}

# A name that starts with a dot is never the site's: the deploy copies
# public/.gitignore and public/files/.gitignore along, and an editor or
# a checkout can leave more (.git/, .env, .swp). Only /.well-known/ is
# meant to be read, by name below. The first regex location, so no
# other one (a .css, a .png) answers for such a name first.
location ~ /\.(?!well-known/) {
    return 404;
}
# How to report a security problem (RFC 9116); its Expires is renewed
# once a year (donate/test_deploy_content.py fails once it has passed).
location = /.well-known/security.txt {
    types { }
    default_type text/plain;
    add_header Cache-Control "public, max-age=86400";
    try_files $uri =404;
}
